mapper.sql:
SELECT de.* FROM (
SELECT
@rownum := @rownum + 1 'rownum',
OCODE 	OCODE,
MARKETID 	MARKETID,
ORGID	ORGID,
OTYPE   OTYPE,
GRADEORGID   GRADEORGID,
GRADEDATE    GRADEDATE,
NOTICEDATE    NOTICEDATE,
SHORTLONGTERM 	SHORTLONGTERM,



        MSTRATINGRESULT02 	GRADERESULT,


        MSTRATINGRESULT01 	GRADERESULT,


INPUTTYPE 	INPUTTYPE,
GRADEEXPECTATION     	GRADEEXPECTATION,
DIRECTIONCHANGE		DIRECTIONCHANGE,
ISSUERRATETYPE ISSUERRATETYPE,
INNEROUTER INNEROUTER,
IF
( ( @OCODE = OCODE AND @OTYPE = OTYPE AND @GRADEORGID = GRADEORGID ),
    @rank := @rank + 1,
    @rank := 1
) AS rk,
@OCODE := OCODE,
@OTYPE := OTYPE,
@GRADEORGID := GRADEORGID
FROM
( SELECT * FROM view_fin_product_rating ORDER BY OCODE, OTYPE, GRADEORGID ) b,
( SELECT @rownum := 0, @BOOKSET_ID := NULL, @BAL_DATE := NULL, @O_CCY := NULL, @rank := 0 ) a
where
1=1

    AND ${sqlSearchString}



    AND OCODE = #{oCode,jdbcType=VARCHAR}



    AND GRADEORGID = #{gradeOrgId,jdbcType=VARCHAR}



    AND GRADEDATE = STR_TO_DATE(#{gradeDateStr,jdbcType=VARCHAR}, '%Y-%m-%d')



    AND GRADEDATE  >=  STR_TO_DATE(#{gradeDateStart,jdbcType=VARCHAR}, '%Y-%m-%d')



    AND GRADEDATE  <=  STR_TO_DATE(#{gradeDateEnd,jdbcType=VARCHAR}, '%Y-%m-%d')



    AND INNEROUTER = #{gradeSourceType,jdbcType=VARCHAR}



    AND shortLongTerm = #{shortLongTerm,jdbcType=VARCHAR}



    AND oType = #{oType,jdbcType=VARCHAR}



    AND MSTRATINGRESULT01 = #{gradeResult,jdbcType=VARCHAR}

) de WHERE 1=1


    AND de.rk = 1

with a as (
SELECT asset_code,rating FROM (
select row_number() over(partition by brating.O_CODE order by brating.O_CODE,brating.GRADE_DATE desc
/*推荐评级*/
    ,brating.is_recommand asc

/*最大评级*/
    ,brating.GRADE_RESULT asc

/*最小评级*/
    ,brating.GRADE_RESULT desc

) my_rank
,brating.O_CODE as asset_code
,brating.GRADE_RESULT as rating
from MST_BOND_CREDIT_RATING brating
where 1=1
and brating.O_TYPE = '01' /*主体评级*/
and brating.SHORT_LONG_TERM = '02' /*长期*/
and brating.GRADE_DATE<=#{enddate,jdbcType=DATE}
) as t where my_rank=1
) ,
 b as
 (
 SELECT asset_code,rating FROM (
 select row_number() over(partition by brating.O_CODE order by brating.O_CODE,brating.GRADE_DATE desc
 /*推荐评级*/
     ,brating.is_recommand asc

 /*最大评级*/
     ,brating.GRADE_RESULT asc

 /*最小评级*/
     ,brating.GRADE_RESULT desc

 ) my_rank
 ,brating.O_CODE as asset_code
 ,brating.GRADE_RESULT as rating
 from MST_BOND_CREDIT_RATING brating
 where 1=1
 and brating.O_TYPE = '01' /*主体评级*/
 and brating.SHORT_LONG_TERM = '01' /*短期*/
and brating.GRADE_DATE<=#{enddate,jdbcType=DATE}
)as t where my_rank=1
),
c as
(
SELECT asset_code,rating FROM (
select row_number() over(partition by brating.O_CODE order by brating.O_CODE,brating.GRADE_DATE desc
/*推荐评级*/
    ,brating.is_recommand asc

/*最大评级*/
    ,brating.GRADE_RESULT asc

/*最小评级*/
    ,brating.GRADE_RESULT desc

) my_rank
,brating.O_CODE as asset_code
,brating.GRADE_RESULT as rating
from MST_BOND_CREDIT_RATING brating
where 1=1
and brating.O_TYPE = '02' /*债项评级*/
and brating.SHORT_LONG_TERM = '02' /*长期*/
and brating.GRADE_DATE<=#{enddate,jdbcType=DATE}
)as t where my_rank=1
)
,

d as(
SELECT asset_code,rating FROM (
select row_number() over(partition by brating.O_CODE order by brating.O_CODE,brating.GRADE_DATE desc
/*推荐评级*/
    ,brating.is_recommand asc

/*最大评级*/
    ,brating.GRADE_RESULT asc

/*最小评级*/
    ,brating.GRADE_RESULT desc

) my_rank
,brating.O_CODE as asset_code
,brating.GRADE_RESULT as rating
from MST_BOND_CREDIT_RATING brating
where 1=1
and brating.O_TYPE = '02' /*债项评级*/
and brating.SHORT_LONG_TERM = '01' /*短期*/
and brating.GRADE_DATE<=#{enddate,jdbcType=DATE}
) as t where my_rank=1
)

