select #{bookdate,jdbcType=DATE} bookdate ,#{enddate,jdbcType=DATE} enddate ,pos.INVEST_VARIETY ,pos.trade_type ,pos.IS_UNDER_TRADE ,pos.ASSET_CODE ,pos.PROD_ID ,pos.chl_id chlid ,pos.CCY ,(case pos.ASSET_CODE when 'REMAININGCASH' then '01' else info.asset_type end) assettype ,(case pos.ASSET_CODE when 'REMAININGCASH' then '1001' else info.ASSET_TYPE2 end) assettype2 ,ifnull(ifnull(info.PRO_INDUSTRY,info.INDUSTRY1),info.INDUSTRY_SHARES) INDUSTRY1 /*所属行业*/ ,info.IN_ASSET_TYPE IN_ASSET_TYPE /*行业一级分类*/ ,sum(pos.accuamt) ASSETVALUE_A /*穿透前资产价值*/ ,sum((case pos.trade_type when '05' then pos.accuqty else null end)) ASSETVALUE_B /*穿透后资产价值*/ ,ifnull(ifnull(c.rating ,d.rating),ifnull(a.rating,b.rating)) rating/*债券评级*/ ,(case info.PRIVATE_FLAG when '01' then '01' else null end) MONIT_TYPE ,(case info.PPPFLAG when '01' then '01' else null end) PPPFLAG ,(case info.IS_GOVERN_FUND when '01' then '01' else null end) IS_GOVERN_FUND1 ,(case info.PRIVATEFUND_FLAG when '01' then '01' else null end) PRIVATEFUND_FLAG ,(case info.PRIVATEPRD_FLAG when '01' then '01' else null end) PRIVATEPRD_FLAG ,(case info.BONDTOSTOCK_FLAG when '01' then '01' else null end) BONDTOSTOCK_FLAG ,info.MANAGE_TYPE MANAGE_TYPE /*管理方式*/ ,prd.IS_FHXGCP /**是否合新规*/ from CHB_ASSET_POSITION pos left join CHB_ASSET_INFO info on pos.ASSET_CODE=info.ASSET_CODE and info.status !='D'
left join ( SELECT asset_code,rating FROM ( select @rownum := @rownum + 1 'rownum' ,brating.O_CODE as asset_code ,brating.GRADE_RESULT as rating, IF( @O_CODE = brating.O_CODE, @rank := @rank + 1, @rank := 1 ) AS my_rank, @O_CODE := brating.O_CODE from ( SELECT * FROM MST_BOND_CREDIT_RATING ORDER BY O_CODE, GRADE_DATE desc /*推荐评级*/ ,is_recommand asc
